//
// EvilGenius's install page: fm1-base's web installer (fm1lib.js: its fm1pkg.js and fm1ota.js, generated by
// firmware/tools/sync_installer.py) driven as FIZZ's install page drives it, for one package that carries its own
// data:
//   - the firmware is chosen from ../firmware/releases.json (the latest by default, ?v=VERSION to pick one), checked
//     against its size, its SHA-256 and its identity before it is offered;
//   - Install: the running firmware checks the package and starts the package's update loader, which writes the
//     program and EvilGenius's two data regions; an FM-1 already in update mode (an install that was cut off) is
//     finished from there;
//   - everything goes over USB (never a Bluetooth MIDI port);
//   - Check my FM-1 says what the unit runs; Going back installs M-VAVE's own firmware file.
import { productOf, logicalImage, ufwEntries, Updater, IS_OTA, IS_STOCK } from "./fm1lib.js";
import { md, esc } from "./notes.js";

const $ = (id) => document.getElementById(id);
const INDEX = "../firmware/releases.json";
const PREFIX = "FM-1_45";                       // firmware/app/fm1.toml id_prefix
const TEXT = {
  nomidi: "This browser can't talk to the FM-1 (no Web MIDI). Open this page in Chrome or Edge on a computer.",
  loadfail: "Could not load the firmware: ",
  noindex: "No EVILGENIUS release is published yet.",
  ready: "is ready to install.",
  start: "Starting", verify: "Checking the package", loader: "Switching to update mode", write: "Writing EVILGENIUS",
  reboot: "Restarting",
  done: "Done. EVILGENIUS is installed and running.",
  stopped: "Stopped. Replug the USB cable and press Install again.",
  error: "Error: ",
  denied: "MIDI (SysEx) access was not allowed. Allow MIDI in the site settings (the address bar) and press Install again.",
  notfound: "FM-1 not found. Check the USB cable (a data cable), close other apps and browser tabs that use MIDI, and press Install again.",
  model: "The connected device is not an FM-1.",
  open: "This FM-1 runs M-VAVE's Open firmware. Put the stock firmware back first (Going back, below), then install EVILGENIUS.",
  lost: "The USB connection was lost. Replug it and press Install again.",
  noloader: "The FM-1 in update mode was not found. Replug the USB cable and press Install again (it stays in update mode until it is finished).",
  noreturn: "The FM-1 did not come back. Switch it off and on.",
  mismatch: "Written, but the FM-1 reports another version: ",
  badpkg: "The firmware file is damaged or not the one listed. Reload the page.",
  badreq: "The FM-1 asked for something outside the file. Nothing more was written. ",
  leave: "Writing. Do not close the page.",
  stockok: "That is M-VAVE's FM-1 firmware. Press the button to install it.",
  stockbad: "That is not M-VAVE's FM-1 firmware.",
  stockdone: "Done. The FM-1 has restarted with M-VAVE's firmware.",
  checking: "Looking for the FM-1…",
};

const log = (s) => { const el = $("log"); el.textContent += s + "\n"; el.scrollTop = el.scrollHeight; };
function say(text, cls = "") { const el = $("status"); el.textContent = text; el.className = "status " + cls; }
function alertK(k, extra = "") { $("alert").textContent = k ? TEXT[k] + (extra || "") : ""; if (k) say(""); }
function bar(pct) {
  const p = Math.max(0, Math.min(100, pct));
  $("barfill").style.width = p + "%";
  $("bar").setAttribute("aria-valuenow", String(Math.round(p)));
}
const hex = async (raw) => [...new Uint8Array(await crypto.subtle.digest("SHA-256", raw))].map((b) => b.toString(16).padStart(2, "0")).join("");
const isBlePort = (name) => /\sbluetooth$/i.test(String(name || "").trim());
/* the access without a Bluetooth MIDI port: an install goes over USB only */
function usbOnly(access) {
  const usb = (m) => new Map([...m].filter(([, x]) => !isBlePort(x.name)));
  return { get inputs() { return usb(access.inputs); }, get outputs() { return usb(access.outputs); } };
}

let releases = [], chosen = null, stock = null, writing = false;

function busy(on) {
  writing = on;
  $("go").disabled = on || !chosen || !navigator.requestMIDIAccess;
  $("check").disabled = on;
  $("stockgo").disabled = on || !stock;
  $("version").disabled = on || releases.length < 2;
  window.onbeforeunload = on ? () => TEXT.leave : null;
}

async function choose(v) {
  chosen = null;
  $("go").disabled = true;
  const rel = releases.find((r) => r.version === v) || releases[0];
  if (!rel) { alertK("noindex"); return; }
  const pkg = (rel.packages || [])[0];
  $("notes").innerHTML = md(rel.notes || "");
  $("pkginfo").textContent = `${rel.date || ""} · ${rel.channel === "beta" ? "beta" : "release"}`;
  say("Loading the firmware", "busy");
  try {
    const f = pkg.fwsc;
    const r = await fetch("../firmware/" + f.path, { cache: "no-cache" });
    if (!r.ok) throw new Error(`${f.path}: ${r.status}`);
    const raw = new Uint8Array(await r.arrayBuffer());
    if (raw.length !== f.bytes || await hex(raw) !== f.sha256 || productOf(raw) !== rel.identity || !rel.identity.startsWith(PREFIX)) {
      alertK("badpkg");
      return;
    }
    chosen = { rel, image: logicalImage(raw), product: rel.identity, sha256: f.sha256, bytes: raw.length };
    alertK("");
    $("pkginfo").textContent += ` · ${(raw.length / 1024).toFixed(0)} KB · ${rel.identity}`;
    if (navigator.requestMIDIAccess) { say(`EVILGENIUS ${rel.version} ${TEXT.ready}`, "ok"); $("go").disabled = writing; }
    else say("");
  } catch (e) {
    alertK("loadfail", e && e.message);
  }
}

async function load() {
  if (!navigator.requestMIDIAccess) $("nomidi").hidden = false;
  try {
    const r = await fetch(INDEX, { cache: "no-cache" });
    if (!r.ok) throw new Error(String(r.status));
    releases = (await r.json()).releases || [];
  } catch (e) {
    releases = [];
  }
  const sel = $("version");
  sel.textContent = "";
  if (!releases.length) {
    sel.append(new Option("none yet", ""));
    alertK("noindex");
    return;
  }
  for (const r of releases) sel.append(new Option(`${r.version}${r === releases[0] ? " (latest)" : ""}`, r.version));
  const want = new URLSearchParams(location.search).get("v");
  sel.value = releases.some((r) => r.version === want) ? want : releases[0].version;
  sel.disabled = releases.length < 2;
  sel.addEventListener("change", () => choose(sel.value));
  await choose(sel.value);
}

async function run(img, product, isStock, sha256) {
  let midi;
  alertK("");
  try { midi = await navigator.requestMIDIAccess({ sysex: true }); }
  catch (e) { alertK("denied"); return; }
  busy(true);
  bar(0);
  try {
    const up = new Updater(usbOnly(midi), log);
    /* progress: the bytes the device reads against what it reads for this package (FIZZ's install page's sum).
       Step 1 (the running firmware): the header, the loader's head twice, its body. Step 2 (the loader): the header,
       the key check, the whole flash.bin (checked before anything is erased), then what it writes. Held at 99 until
       the device comes back */
    const ent = ufwEntries(img), fl = ent[0], ldr = ent[100];
    const CHECK = 0x400 + 0x400 + (ldr ? ldr.len - 0x20 : 0);
    const WRITE = fl && fl.len > 0x4000 && fl.len <= 0x100000 ? 0x400 + 0x20 + fl.len + (fl.len - 0x4000) : img.length;
    const total = CHECK + WRITE;
    const step = (k, a, b) => {
      log(`${k} ${a ?? ""}`);
      if (k === "start") say(TEXT.start, "busy");
      if (k === "verify") { bar((Math.min(b, CHECK) / total) * 100); say(TEXT.verify, "busy"); }
      if (k === "loader") say(TEXT.loader, "busy");
      if (k === "write") { bar(Math.min(99, ((CHECK + b) / total) * 100)); say(TEXT.write, "busy"); }
      if (k === "reboot") say(TEXT.reboot, "busy");
    };
    const ota = await up.find((id) => /^ota-/i.test(id.model));
    let done = true;
    if (ota) {                                         // an install that was cut off: finished from update mode
      ota.link.close();
      done = await up.resume(img, step, product);
    } else {
      await up.install(img, product, step, sha256);
    }
    if (!done) alertK("stopped");
    else { bar(100); say(isStock ? TEXT.stockdone : TEXT.done, "ok"); }
  } catch (e) {
    if (isStock && e && e.code === "mismatch") { bar(100); say(TEXT.stockdone, "ok"); }   // (stock names itself its own way)
    else if (e && e.code && TEXT[e.code]) alertK(e.code, e.code === "mismatch" ? (e.detail || "") : e.code === "badreq" ? e.message : "");
    else alertK("error", e && e.message);
    log(String((e && e.stack) || e));
  }
  busy(false);
}

async function check() {
  alertK("");
  if (!navigator.requestMIDIAccess) { alertK("nomidi"); return; }
  let midi;
  try { midi = await navigator.requestMIDIAccess({ sysex: true }); }
  catch (e) { alertK("denied"); return; }
  say(TEXT.checking, "busy");
  try {
    const dev = await new Updater(usbOnly(midi), log).find(() => true);
    if (!dev) { alertK("notfound"); return; }
    const id = dev.id;
    dev.link.close();
    const what = IS_OTA(id) ? "is in update mode (an install was cut off): press Install to finish it"
      : IS_STOCK(id.text) ? "runs M-VAVE's own firmware"
      : id.text.startsWith(PREFIX) ? "runs EVILGENIUS"
      : "runs another firmware";
    say(`This FM-1 ${what} (${esc(id.text)}).`, "ok");
  } catch (e) {
    alertK(e && e.code && TEXT[e.code] ? e.code : "error", e && !TEXT[e.code] ? e.message : "");
  }
}

$("go").addEventListener("click", () => { if (chosen) run(chosen.image, chosen.product, false, chosen.sha256); });
$("check").addEventListener("click", check);
$("stockfile").addEventListener("change", async (ev) => {
  stock = null;
  $("stockgo").disabled = true;
  const f = ev.target.files && ev.target.files[0];
  if (!f) return;
  const raw = new Uint8Array(await f.arrayBuffer());
  let product = "";
  try { product = productOf(raw); } catch (e) { product = ""; }
  if (!IS_STOCK(product)) {
    $("stockstatus").textContent = TEXT.stockbad;
    $("stockstatus").className = "status err";
    return;
  }
  stock = { image: logicalImage(raw), product, sha256: await hex(raw) };
  $("stockstatus").textContent = TEXT.stockok;
  $("stockstatus").className = "status ok";
  $("stockgo").disabled = writing;
});
$("stockgo").addEventListener("click", () => { if (stock) run(stock.image, stock.product, true, stock.sha256); });

load();
